    /** The program run on its own (no JCL step, no CICS task, no caller): the PROCEDURE DIVISION from its
     *  initial storage; RETURN-CODE. */
    public int runProgram() {
        initialState();
        performDepth = 0;
        try {
            perform(0, 19);
        } catch (Goback g) {
            // the program ended
        }
        return Cobol.num(f1107_GG_RETURN_CODE, CS).intValue();
    }

    /** One task of the program: the EIB and COMMAREA from the task, then the PROCEDURE DIVISION. */
    public void runTask(CicsTask task) {
        boolean truncBefore = Cobol.swapTruncBinary(true);  // TRUNC(STD)
        boolean pfdBefore = Cobol.swapNumprocPfd(false);  // NUMPROC(NOPFD)
        try {
            this.task = task;
            caBack = () -> { };
            handlers.clear();
            heldKey.clear();
            initialState();
            Cobol.move(task.transid(), f1078_EIBTRNID, CS);
            Cobol.move(task.termid() == null ? "" : task.termid(), f1080_EIBTRMID, CS);
            Cobol.store(f1079_EIBTASKN, BigDecimal.valueOf(task.taskNumber()), false, CS);
            java.time.LocalDateTime now = task.now();
            Cobol.store(f1077_EIBDATE, BigDecimal.valueOf((now.getYear() - 1900) * 1000L + now.getDayOfYear()), false, CS);
            Cobol.store(f1076_EIBTIME, BigDecimal.valueOf(now.getHour() * 10000L + now.getMinute() * 100L + now.getSecond()), false, CS);
            switch (task.aid() == null ? "" : task.aid()) {
                case "NULL" -> Cobol.move(f969_DFHNULL, f1084_EIBAID, CS);
                case "ENTER" -> Cobol.move(f970_DFHENTER, f1084_EIBAID, CS);
                case "CLEAR" -> Cobol.move(f971_DFHCLEAR, f1084_EIBAID, CS);
                case "CLRP" -> Cobol.move(f972_DFHCLRP, f1084_EIBAID, CS);
                case "PEN" -> Cobol.move(f973_DFHPEN, f1084_EIBAID, CS);
                case "OPID" -> Cobol.move(f974_DFHOPID, f1084_EIBAID, CS);
                case "MSRE" -> Cobol.move(f975_DFHMSRE, f1084_EIBAID, CS);
                case "STRF" -> Cobol.move(f976_DFHSTRF, f1084_EIBAID, CS);
                case "TRIG" -> Cobol.move(f977_DFHTRIG, f1084_EIBAID, CS);
                case "PA1" -> Cobol.move(f978_DFHPA1, f1084_EIBAID, CS);
                case "PA2" -> Cobol.move(f979_DFHPA2, f1084_EIBAID, CS);
                case "PA3" -> Cobol.move(f980_DFHPA3, f1084_EIBAID, CS);
                case "PF1" -> Cobol.move(f981_DFHPF1, f1084_EIBAID, CS);
                case "PF2" -> Cobol.move(f982_DFHPF2, f1084_EIBAID, CS);
                case "PF3" -> Cobol.move(f983_DFHPF3, f1084_EIBAID, CS);
                case "PF4" -> Cobol.move(f984_DFHPF4, f1084_EIBAID, CS);
                case "PF5" -> Cobol.move(f985_DFHPF5, f1084_EIBAID, CS);
                case "PF6" -> Cobol.move(f986_DFHPF6, f1084_EIBAID, CS);
                case "PF7" -> Cobol.move(f987_DFHPF7, f1084_EIBAID, CS);
                case "PF8" -> Cobol.move(f988_DFHPF8, f1084_EIBAID, CS);
                case "PF9" -> Cobol.move(f989_DFHPF9, f1084_EIBAID, CS);
                case "PF10" -> Cobol.move(f990_DFHPF10, f1084_EIBAID, CS);
                case "PF11" -> Cobol.move(f991_DFHPF11, f1084_EIBAID, CS);
                case "PF12" -> Cobol.move(f992_DFHPF12, f1084_EIBAID, CS);
                case "PF13" -> Cobol.move(f993_DFHPF13, f1084_EIBAID, CS);
                case "PF14" -> Cobol.move(f994_DFHPF14, f1084_EIBAID, CS);
                case "PF15" -> Cobol.move(f995_DFHPF15, f1084_EIBAID, CS);
                case "PF16" -> Cobol.move(f996_DFHPF16, f1084_EIBAID, CS);
                case "PF17" -> Cobol.move(f997_DFHPF17, f1084_EIBAID, CS);
                case "PF18" -> Cobol.move(f998_DFHPF18, f1084_EIBAID, CS);
                case "PF19" -> Cobol.move(f999_DFHPF19, f1084_EIBAID, CS);
                case "PF20" -> Cobol.move(f1000_DFHPF20, f1084_EIBAID, CS);
                case "PF21" -> Cobol.move(f1001_DFHPF21, f1084_EIBAID, CS);
                case "PF22" -> Cobol.move(f1002_DFHPF22, f1084_EIBAID, CS);
                case "PF23" -> Cobol.move(f1003_DFHPF23, f1084_EIBAID, CS);
                case "PF24" -> Cobol.move(f1004_DFHPF24, f1084_EIBAID, CS);
                default -> { }
            }
            Object ca = task.hasCommarea() ? task.commarea(Object.class) : null;
            int calen = 0;
            if (ca instanceof Copaus0cCarddemoCommarea x) {
                in_Copaus0cCarddemoCommarea(x, s_DFHCOMMAREA, 0);
                caBack = () -> fill_Copaus0cCarddemoCommarea(x, s_DFHCOMMAREA, 0);
                calen = cx(task, 380);
            }
            s_DFHCOMMAREA.beyond = null;
            if (ca instanceof byte[] cb0) {
                byte[] cb = DetCics.commareaIn(cb0, CS);
                System.arraycopy(cb, 0, s_DFHCOMMAREA.bytes, 0, Math.min(cb.length, s_DFHCOMMAREA.bytes.length));
                if (cb.length > s_DFHCOMMAREA.bytes.length) {
                    s_DFHCOMMAREA.beyond = java.util.Arrays.copyOfRange(cb, s_DFHCOMMAREA.bytes.length, cb.length);
                }
                calen = cx(task, cb.length);
            }
            byte[] raw = task.linkArea();
            if (raw != null) {
                System.arraycopy(raw, 0, s_DFHCOMMAREA.bytes, 0, Math.min(raw.length, s_DFHCOMMAREA.bytes.length));
                int keep = s_DFHCOMMAREA.bytes.length;
                s_DFHCOMMAREA.beyond = raw.length > keep ? java.util.Arrays.copyOfRange(raw, keep, raw.length) : null;
                Runnable typed = caBack;
                caBack = () -> { typed.run(); System.arraycopy(s_DFHCOMMAREA.bytes, 0, raw, 0, Math.min(raw.length, keep)); if (s_DFHCOMMAREA.beyond != null) { System.arraycopy(s_DFHCOMMAREA.beyond, 0, raw, keep, raw.length - keep); } };
            }
            byte[] caWhole = null;
            if (task.exactCommarea() && calen < s_DFHCOMMAREA.bytes.length) {
                caWhole = s_DFHCOMMAREA.bytes;
                s_DFHCOMMAREA.bytes = java.util.Arrays.copyOf(caWhole, calen);
                Runnable typed = caBack;
                byte[] whole = caWhole;
                caBack = () -> { caWhole(whole); typed.run(); };
            }
            Cobol.store(f1083_EIBCALEN, BigDecimal.valueOf(calen), false, CS);
            try {
                try {
                    perform(0, 19);
                } catch (Goback g) {
                    // RETURN / XCTL / an abend ended the program
                }
            } catch (IndexOutOfBoundsException e) {
                if (caWhole == null) {
                    throw e;
                }
                throw new DetCics.PastFrom("COMMAREA past EIBCALEN (" + calen + " bytes): not modelled");
            } finally {
                if (caWhole != null) {
                    caWhole(caWhole);
                }
            }
            if (!task.ended()) {
                caBack.run();
                task.returnTransid(null, null);  // a GOBACK is a RETURN
            }
        } finally {
            Cobol.swapTruncBinary(truncBefore);
            Cobol.swapNumprocPfd(pfdBefore);
        }
    }

    public Object handleTransaction(String transid, Copaus0cCarddemoCommarea request) {
        CicsTask.Region region = CicsTask.region();
        CicsTask task = region.transaction(transid, request);
        region.run(task, "COPAUS0C", this::runTask);
        return task.returned(Object.class);
    }

    public Object handleTransaction(String transid, Copaus0cCarddemoCommarea request, byte[] area) {
        CicsTask.Region region = CicsTask.region();
        CicsTask task = region.transaction(transid, request, area);
        region.run(task, "COPAUS0C", this::runTask);
        lastAnswerBytes = task.returnedBytes();
        return task.returned(Object.class);
    }

    public Copaus0cCarddemoCommarea handleLink(Copaus0cCarddemoCommarea request) {
        CicsTask.Region region = CicsTask.region();
        CicsTask task = region.linked("COPAUS0C", request);
        region.run(task, "COPAUS0C", this::runTask);
        return request;
    }

    public Copaus0cCarddemoCommarea handleLink(Copaus0cCarddemoCommarea request, byte[] area) {
        CicsTask.Region region = CicsTask.region();
        CicsTask task = region.linked("COPAUS0C", request, area);
        region.run(task, "COPAUS0C", this::runTask);
        byte[] left = task.linkAreaView();
        lastLinkBytes = task.linkAreaTaken() && left != null ? java.util.Arrays.copyOf(left, left.length) : null;
        return request;
    }

    // @facade-helper: the bytes the last byte-carrying handleTransaction answered
    private byte[] lastAnswerBytes;

    /** The bytes the last byte-carrying handleTransaction's RETURN passed on (a copy; null: none).
     *  @facade-helper */
    public byte[] lastAnswerBytes() {
        return lastAnswerBytes == null ? null : java.util.Arrays.copyOf(lastAnswerBytes, lastAnswerBytes.length);
    }

    // @facade-helper: the bytes the last byte-carrying handleLink's program left in the COMMAREA
    private byte[] lastLinkBytes;

    /** The bytes the last byte-carrying handleLink's program left in the LINK COMMAREA (a copy; null: it
     *  took none -- its DTO is the COMMAREA). @facade-helper */
    public byte[] lastLinkBytes() {
        return lastLinkBytes == null ? null : java.util.Arrays.copyOf(lastLinkBytes, lastLinkBytes.length);
    }


    /** GOBACK / STOP RUN. */
    private static final class Goback extends RuntimeException {
        private static final long serialVersionUID = 1L;

        Goback() {
            super(null, null, false, false);
        }
    }

    private static Dd dd(List<Dd> dds, String name) {
        return dds.stream().filter(d -> name.equals(d.name())).findFirst().orElse(null);
    }

    /** The batch entry. */
    public int runBatch(List<Dd> dds, String parm) {
        boolean truncBefore = Cobol.swapTruncBinary(true);  // TRUNC(STD)
        boolean pfdBefore = Cobol.swapNumprocPfd(false);  // NUMPROC(NOPFD)
        try {
            initialState();
            try {
                perform(0, 19);
            } catch (Goback g) {
                // the program ended
            }
            return Cobol.num(f1107_GG_RETURN_CODE, CS).intValue();
        } finally {
            Cobol.swapTruncBinary(truncBefore);
            Cobol.swapNumprocPfd(pfdBefore);
        }
    }

    /** The active PERFORMs' last paragraphs, outermost first. */
    private int[] performThru = new int[64];
    private int performDepth = 0;

    /** Control reached the end of an outer active PERFORM's range: that PERFORM returns (`depth`). */
    private static final class PerformExit extends RuntimeException {
        private static final long serialVersionUID = 1L;
        final int depth;

        PerformExit(int depth) {
            super(null, null, false, false);
            this.depth = depth;
        }
    }

    /** PERFORM from THRU thru. When control falls off the end of a paragraph, the innermost active PERFORM
     *  whose range ends there returns -- this one, or an outer one a GO TO reached the end of, abandoning
     *  the PERFORMs inside it (GnuCOBOL, as IBM: test_det_programs.py, GOTOOUT). */
    private void perform(int from, int thru) {
        int mine = performDepth;
        if (mine == performThru.length) {
            performThru = java.util.Arrays.copyOf(performThru, mine * 2);
        }
        performThru[performDepth++] = thru;
        try {
            int i = from;
            while (true) {
                int next = run(i);
                boolean jumped = (next & GOTO) != 0;
                next &= ~GOTO;
                if (!jumped) {
                    if (i == thru) {
                        return;
                    }
                    for (int d = mine - 1; d >= 0; d--) {
                        if (performThru[d] == i) {
                            throw new PerformExit(d);
                        }
                    }
                }
                if (next >= 20) {
                    throw new Goback();
                }
                i = next;
            }
        } catch (PerformExit e) {
            if (e.depth != mine) {
                throw e;
            }
        } finally {
            performDepth = mine;
        }
    }

    private int run(int i) {
        switch (i) {
            case 0: return p0();
            case 1: return p1();
            case 2: return p2();
            case 3: return p3();
            case 4: return p4();
            case 5: return p5();
            case 6: return p6();
            case 7: return p7();
            case 8: return p8();
            case 9: return p9();
            case 10: return p10();
            case 11: return p11();
            case 12: return p12();
            case 13: return p13();
            case 14: return p14();
            case 15: return p15();
            case 16: return p16();
            case 17: return p17();
            case 18: return p18();
            case 19: return p19();
            default: throw new IllegalStateException("paragraph " + i);
        }
    }

    /** MAIN-PARA. */
