            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 273, 8, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 281, 8, false), CS);
