            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 321, 8, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 329, 8, false), CS);
            Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 337, 4, 0, true, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 339, 1, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 340, 8, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 348, 8, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 356, 8, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 364, 8, false), CS);
            Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f48_CARDDEMO_COMMAREA.storage(), f48_CARDDEMO_COMMAREA.offset() + 372, 8, false), CS);
            // MOVE WS-PGM-AUTH-SMRY TO CDEMO-TO-PROGRAM
            Cobol.move(f2_WS_PGM_AUTH_SMRY, f53_CDEMO_TO_PROGRAM, CS);
            // SET CDEMO-PGM-REENTER TO TRUE
            Cobol.move(D1, f56_CDEMO_PGM_CONTEXT, CS);
            // MOVE LOW-VALUES TO COPAU0AO
            Cobol.moveFigurative(Figurative.LOW_VALUES, f452_COPAU0AO, CS);
            // MOVE -1 TO ACCTIDL OF COPAU0AI
            Cobol.move(DM1, f116_ACCTIDL, CS);
            // PERFORM SEND-PAULST-SCREEN
            perform(11, 11);
