            Cobol.string(f6_WS_MESSAGE, null, CS, Cobol.StringPart.size("Customer:", CS), Cobol.StringPart.size(f31_WS_CARD_RID_CUST_ID_X), Cobol.StringPart.size(" System error while reading CUST file. Resp:", CS), Cobol.StringPart.size(f17_WS_RESP_CD_DIS), Cobol.StringPart.size(" Reas:", CS), Cobol.StringPart.size(f18_WS_REAS_CD_DIS));
