    /** GET-AUTH-SUMMARY. */
    private int p18() {
        // PERFORM SCHEDULE-PSB
        perform(19, 19);
        // MOVE CDEMO-ACCT-ID TO PA-ACCT-ID
        Cobol.move(f63_CDEMO_ACCT_ID, f925_PA_ACCT_ID, CS);
        // EXEC DLI GU USING PCB(PAUT-PCB-NUM) SEGMENT (PAUTSUM0) INTO (PENDING-AUTH-SUMMARY) WHERE (ACCNTID = PA-ACCT-ID) END-EXEC
        Cobol.move(com.gitgalaxy.modernized.cobolrt.dli.DetDli.get("GU", BigDecimal.valueOf(f37_PAUT_PCB_NUM).intValue(), f924_PENDING_AUTH_SUMMARY, com.gitgalaxy.modernized.cobolrt.dli.DetDli.ssa("PAUTSUM0", "ACCNTID", "EQ", f925_PA_ACCT_ID)), f1110_DIBSTAT, CS);
        // MOVE DIBSTAT TO IMS-RETURN-CODE
        Cobol.move(f1110_DIBSTAT, f38_IMS_RETURN_CODE, CS);
        // EVALUATE TRUE
        if ((isStatusOk())) {
            // SET FOUND-PAUT-SMRY-SEG TO TRUE
            f44_WS_PAUT_SMRY_SEG_FLG = "Y";
        } else if ((isSegmentNotFound())) {
            // SET NFOUND-PAUT-SMRY-SEG TO TRUE
            f44_WS_PAUT_SMRY_SEG_FLG = "N";
        } else if (true) {
            // MOVE 'Y' TO WS-ERR-FLG
            f45_WS_ERR_FLG = "Y";
            // STRING ' System error while reading AUTH Summary: Code:' IMS-RETURN-CODE DELIMITED BY SIZE INTO WS-MESSAGE
            Cobol.string(f6_WS_MESSAGE, null, CS, Cobol.StringPart.size(" System error while reading AUTH Summary: Code:", CS), Cobol.StringPart.size(f38_IMS_RETURN_CODE));
            // MOVE -1 TO ACCTIDL OF COPAU0AI
            Cobol.move(DM1, f116_ACCTIDL, CS);
            // PERFORM SEND-PAULST-SCREEN
            perform(11, 11);
        }
        return 19;
    }

    /** SCHEDULE-PSB. */
    private int p19() {
        // EXEC DLI SCHD PSB((PSB-NAME)) NODHABEND END-EXEC
        Cobol.move(com.gitgalaxy.modernized.cobolrt.dli.DetDli.schedule(f35_PSB_NAME, true), f1110_DIBSTAT, CS);
        // MOVE DIBSTAT TO IMS-RETURN-CODE
        Cobol.move(f1110_DIBSTAT, f38_IMS_RETURN_CODE, CS);
        // IF PSB-SCHEDULED-MORE-THAN-ONCE
        if (isPsbScheduledMoreThanOnce()) {
            // EXEC DLI TERM END-EXEC
            Cobol.move(com.gitgalaxy.modernized.cobolrt.dli.DetDli.terminate(), f1110_DIBSTAT, CS);
            // EXEC DLI SCHD PSB((PSB-NAME)) NODHABEND END-EXEC
            Cobol.move(com.gitgalaxy.modernized.cobolrt.dli.DetDli.schedule(f35_PSB_NAME, true), f1110_DIBSTAT, CS);
            // MOVE DIBSTAT TO IMS-RETURN-CODE
            Cobol.move(f1110_DIBSTAT, f38_IMS_RETURN_CODE, CS);
        }
        // IF STATUS-OK
        if (isStatusOk()) {
            // SET IMS-PSB-SCHD TO TRUE
            f39_WS_IMS_PSB_SCHD_FLG = "Y";
        } else {
            // MOVE 'Y' TO WS-ERR-FLG
            f45_WS_ERR_FLG = "Y";
            // STRING ' System error while scheduling PSB: Code:' IMS-RETURN-CODE DELIMITED BY SIZE INTO WS-MESSAGE
            Cobol.string(f6_WS_MESSAGE, null, CS, Cobol.StringPart.size(" System error while scheduling PSB: Code:", CS), Cobol.StringPart.size(f38_IMS_RETURN_CODE));
            // MOVE -1 TO ACCTIDL OF COPAU0AI
            Cobol.move(DM1, f116_ACCTIDL, CS);
            // PERFORM SEND-PAULST-SCREEN
            perform(11, 11);
        }
        return 20;
    }

